import { Core } from "@strapi/strapi";
import { faker } from "@faker-js/faker";
import { PromisePool } from "@supercharge/promise-pool";

type ProductType = "BOOK";

type CatalogEntity = "BOOK_CATEGORY" | ProductType;

// A type alias rather than an interface, so it is assignable to the JSON attribute.
type BookFilters = {
  /** Slugified genres, as generated by `faker.book.genre()`. */
  category?: string[];
  format?: ("HARDCOVER" | "TRADE_PAPERBACK" | "PAPERBACK")[];
  condition?: ("NEW" | "PRISTINE" | "EXCELLENT" | "GOOD" | "ACCEPTABLE")[];
  /** Upper bound in cents, matching how SKU prices are stored. */
  maxPrice?: number;
  onSale?: boolean;
};

/** UIDs of the components the catalog `layout` dynamic zone accepts. */
enum LayoutComponent {
  Grid = "grid.grid",
  AvatarList = "avatar-list.avatar-list",
}

/** Mirrors the `grid.grid` component. */
interface Grid {
  __component: LayoutComponent.Grid;
  entity: CatalogEntity;
  filters: BookFilters;
}

/** Mirrors the `avatar-list.avatar-list` component. */
interface AvatarList {
  __component: LayoutComponent.AvatarList;
  entity: CatalogEntity;
}

type LayoutItem = Grid | AvatarList;

interface Catalog {
  title: string;
  summary?: string;
  layout: LayoutItem[];
}

// Keyed by url path.
