const FAKE_BOOK_PAGE_COUNT = 25;
const FAKE_FORMATS: NonNullable<BookFilters["format"]> = [
  "HARDCOVER",
  "TRADE_PAPERBACK",
  "PAPERBACK",
];
const FAKE_MAX_PRICES = [1000, 1500, 2000, 2500];
const CONCURRENCY = 5;

export async function seedCatalogs(strapi: Core.Strapi): Promise<void> {
  const catalogs = strapi.documents("api::catalog.catalog");
  if ((await catalogs.count({})) > 0) {
    strapi.log.info("Catalogs have already been seeded");
    return;
  }

  const genres = genreCatalogs();
  const pages: Record<string, Catalog> = {
    ...fakeBookCatalog(FAKE_BOOK_PAGE_COUNT, [
      ...Object.keys(genres),
      ...Object.keys(CATALOGS),
    ]),
    // Curated pages win a url path clash, e.g. "/books/romance/" keeps its summary.
    ...genres,
    ...CATALOGS,
  };

  const payloads = Object.entries(pages).map(
    ([urlPath, { summary, layout, ...page }]) => ({
      urlPath,
      ...page,
      summary: summary ? toBlocks(summary) : undefined,
      layout,
    }),
  );

  await PromisePool.withConcurrency(CONCURRENCY)
    .for(payloads)
    // The pool collects errors by default; rethrow so a failed insert aborts seeding.
    .handleError((error) => {
      throw error;
    })
    .process((data) => catalogs.create({ data, status: "published" }));
  strapi.log.info(`Seeded ${payloads.length} catalogs`);
}

function catalogUrlPath(slug: string): string {
  return `/books/${slug}/`;
}

/** The slug of a genre's own catalog, which is also its value in category filters. */
function genreSlug(genre: string): string {
  return faker.helpers.slugify(genre).toLowerCase();
}

/** The URL path of a genre's own catalog. */
export function genreUrlPath(genre: string): string {
  return catalogUrlPath(genreSlug(genre));
}

/** A single grid listing the books that match `filters`. */
function bookGrid(filters: BookFilters): Grid[] {
  return [{ __component: LayoutComponent.Grid, entity: "BOOK", filters }];
}

/**
 * One catalog per genre `faker.book.genre()` can produce, titled after the genre,
 * so every book category has a landing page to link to.
 */
function genreCatalogs(): Record<string, Catalog> {
  return Object.fromEntries(
    faker.definitions.book.genre.map((genre) => [
      genreUrlPath(genre),
      { title: genre, layout: bookGrid({ category: [genreSlug(genre)] }) },
    ]),
  );
}

/** A plausible landing page slug, such as "gleaming-science-fiction". */
export function generateFakeSlug(genre = faker.book.genre()): string {
  return faker.helpers
    .slugify(`${faker.word.adjective()} ${genre}`)
    .toLowerCase();
}

/** Fake book landing pages, each filtering on one genre, keyed by a unique url path. */
function fakeBookCatalog(
  count: number,
  takenUrlPaths: Iterable<string>,
): Record<string, Catalog> {
  const taken = new Set(takenUrlPaths);
  const pages: Record<string, Catalog> = {};

  while (Object.keys(pages).length < count) {
    const genre = faker.book.genre();
    const slug = generateFakeSlug(genre);
    const urlPath = catalogUrlPath(slug);
    if (taken.has(urlPath)) continue;
    taken.add(urlPath);

    pages[urlPath] = {
      title: titleFromSlug(slug),
      summary: faker.datatype.boolean({ probability: 0.8 })
        ? faker.lorem.sentences({ min: 1, max: 3 })
        : undefined,
      layout: bookGrid({
        category: [genreSlug(genre)],
        // Some pages narrow the genre further, as a merchandiser might.
        format: faker.helpers.maybe(
          () => faker.helpers.arrayElements(FAKE_FORMATS, { min: 1, max: 2 }),
          { probability: 0.3 },
        ),
        maxPrice: faker.helpers.maybe(
          () => faker.helpers.arrayElement(FAKE_MAX_PRICES),
          { probability: 0.2 },
        ),
        onSale: faker.helpers.maybe(() => true, { probability: 0.1 }),
      }),
    };
  }

  return pages;
}

function titleFromSlug(slug: string): string {
  return slug
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

/** Wraps plain text in the single paragraph a Strapi blocks field expects. */
function toBlocks(text: string) {
  return [
    {
      type: "paragraph" as const,
      children: [{ type: "text" as const, text }],
    },
  ];
}
